// Pointer artwork: the five shapes of the reference sheet (angular blue pointers with recessed windows,
// yellow shards and cyan faces) as flat vector paths. Generated by tracing the reference, simplified to
// a couple of reference pixels, and measured from each pointer's tip: x runs right and y runs down, in
// units of one reference pixel (a whole pointer is about 120 tall).
//
//   body   the whole pointer as one shape; the dark channels between its parts are holes (even-odd fill)
//   sil    just its outer outline, without those holes (for the glow and the outline behind it)
//   deep   recessed windows, drawn on the body
//   bright the cyan faces and frames
//   acc    the yellow shards
//
// pointers.ts colours these for the dark and light themes.

export interface PointerShape {
  name: string;
  /** Width and height of the drawing in reference pixels, measured from the tip. */
  size: [number, number];
  body: string;
  sil: string;
  deep?: string;
  bright?: string;
  acc?: string;
}

